```typescript
import { LLMClient, LLMOptions } from '../llm-client';
import { Logger } from '../logger';
import { RawNewsItem, StructuredInsightItem, ExtractionSummary } from '../schema/types';

export interface ExtractorOptions {
  llmClient: LLMClient;              // 依赖注入
  maxParallel?: number;               // 默认 3
  maxRetries?: number;                // 默认 1（补救 prompt 重试）
  minConfidence?: number;             // 默认 0.4, 低于此触发补救
  minConfidenceForReview?: number;    // 默认 0.6, 低于此标记 needs_review
  llmOptions?: LLMOptions;            // 传给 LLMClient 的选项
}

export class NewsExtractor {
  constructor(private options: ExtractorOptions);

  // 核心方法: 逐条处理 RawNewsItem[], 返回结构化结果
  async extractBatch(items: RawNewsItem[]): Promise<{
    items: StructuredInsightItem[];
    summary: ExtractionSummary;
  }>;

  // 处理单条: 抽取 + 校验 + 可能的补救重试
  private async extractOne(item: RawNewsItem): Promise<StructuredInsightItem | null>;

  // 解析 LLM 返回的 JSON 文本
  private parseResponse(responseText: string): unknown;

  // 清理 LLM 输出（去掉可能的 Markdown 代码块标记）
  private cleanJsonResponse(text: string): string;
}
```

**关键逻辑**:

1. `extractBatch()`:
   - 使用 Logger("EXTRACT") 记录 [INFO] 开始抽取
   - 逐条调用 extractOne()，最多 `maxParallel` 并发
   - 实现并发控制: 使用简单的批次循环（每批 maxParallel 条，Promise.all）
   - 统计成功/失败/需复核数量
   - 返回 `{ items: [...], summary: ExtractionSummary }`

2. `extractOne()`:
   - 调用 `buildExtractionPrompt(item)` 构建 prompt
   - 调用 `llmClient.send(prompt, llmOptions)`
   - `cleanJsonResponse()` 去掉可能的 ```json ... ``` 标记
   - `JSON.parse()` 解析响应
   - 用 `StructuredInsightItemSchema.safeParse()` 校验
   - 如果校验失败或 `extraction_confidence < minConfidence` → 触发补救重试
   - 补救重试: 调用 `buildRemedialPrompt()` + `llmClient.send()`
   - 补救后仍失败 → 返回 null（不阻断整体流程）
   - 设置 `needs_review = extraction_confidence < minConfidenceForReview`
   - 如果返回 null，记录 [ERROR] 日志

3. `cleanJsonResponse()`:
   - 检测并移除 ` ```json ` 和 ` ``` ` 标记
   - trim whitespace
   - 返回纯 JSON 字符串

