    ingest: { status: 'success' | 'failed' | 'skipped'; result?: ValidationResult; error?: string };
    extract: { status: 'success' | 'failed' | 'skipped'; itemCount?: number; summary?: ExtractionSummary; error?: string };
    synthesize: { status: 'success' | 'failed' | 'skipped'; report?: DailyReport; error?: string };
    visualize: { status: 'success' | 'failed' | 'skipped'; charts?: GeneratedCharts; error?: string };
  };
  totalDurationMs: number;
}

export class PipelineOrchestrator {
  constructor(private options?: PipelineOptions);

  // 执行完整管道
  async run(): Promise<PipelineResult>;

  // 单阶段方法（供 stage 选项和测试使用）
  private async runIngest(): Promise<ValidationResult>;
  private async runExtract(ingestResult: ValidationResult): Promise<{ items: StructuredInsightItem[]; summary: ExtractionSummary }>;
  private async runSynthesize(items: StructuredInsightItem[]): Promise<DailyReport>;
  private async runVisualize(report: DailyReport, stats: AggregationStats, trends: TrendAnalysis): Promise<GeneratedCharts>;
}
```

**关键逻辑**:

1. **`run()` 方法**:
   ```
   记录开始时间

   if stage <= ingest:
     runIngest() → 如果失败则停止（INGEST 失败后无法继续）

   if stage <= extract:
     runExtract(validItems) → 如果失败: stage={status:'failed'}, 报告中有部分失败说明, 继续

   if stage <= synthesize:
     runSynthesize(extractedItems) → 如果全部失败: stage={status:'failed'}

   if stage <= visualize:
     runVisualize(..., stats, trends) → 如果失败: stage={status:'failed'}, 报告仍有文字内容

   计算总耗时
   返回 PipelineResult
   ```

2. **`runExtract()`**:
   - 创建 `NewsExtractor` 实例
   - 调用 `extractor.extractBatch(validItems)`
   - 如果 extractBatch 抛出异常 → 捕获, 返回空 items + error

3. **`runSynthesize()`**:
   - 创建 `StatsAggregator`, `InsightAnalyzer(llmClient)`, `ReportBuilder`
   - Phase A: aggregator.aggregate(items) → stats
   - Phase B: analyzer.identifyTopEvents(...) → topEvents
   - Phase C: 逐事件 analyzer.analyzeEvent(...) → deepAnalyses[]
   - Phase D: analyzer.analyzeTrends(...) → trends
   - Phase E: analyzer.identifyRisksAndOpportunities(...) → riskOpp
   - Phase F: builder.buildReport(...) + builder.toMarkdown(...)
   - 任何 LLM 调用失败 → 用默认值/空值继续

4. **部分失败处理**:
   - M2: 单条抽取失败（extractOne 返回 null）→ 跳过该条, 继续其他
   - M3: LLM 调用失败 → try-catch, 使用 fallback 值（如 TopEvent[] 为空, 趋势全用默认文本）
   - M4: 图表生成失败 → 记录错误, 返回空字符串

5. **日志输出**:
   - Logger("PIPELINE") 记录每个阶段的 [INFO] 开始/完成
   - [ERROR] 记录失败详情
   - 管道结束时输出总耗时和统计

---

