private buildTopicSummary(charts: GeneratedCharts): string {
  if (!charts.topicSummary) return '<p>暂无话题数据</p>';

  let html = this.escapeHtml(charts.topicSummary);

  // ## xxx → <h3>xxx</h3>
  html = html.replace(/^## (.+)$/gm, '<h3>$1</h3>');
  // ### 🥇/🥈/🥉 xxx → <h4>xxx</h4>
  html = html.replace(/^### (.+)$/gm, '<h4>$1</h4>');
